package data_test

import (
	"testing"

	data "github.com/fourcube/goiban-data"
)

func TestStoreInMemory(t *testing.T) {
	store := data.NewInMemoryStore()
	data := data.BankInfo{Bankcode: "12345", Country: "DE"}

	ok, err := store.Store(data)

	if !ok || err != nil {
		t.Errorf("Test failed: %v %v", ok, err)
	}

	record, _ := store.Find("DE", "12345")

	if *record != data {
		t.Errorf("Failed to find data in store")
	}
}

func TestClearInMemory(t *testing.T) {
	store := data.NewInMemoryStore()
	data := data.BankInfo{Bankcode: "12345", Country: "DE", Source: "Foo"}

	ok, err := store.Store(data)

	if !ok || err != nil {
		t.Errorf("Test failed: %v %v", ok, err)
	}

	store.Clear("Foo")

	record, _ := store.Find("DE", "12345")

	if record != nil {
		t.Errorf("Data not deleted!")
	}
}

package data

import (
	"database/sql"
	"log"
)

var (
	INSERT_BANK_DATA             *sql.Stmt
	SELECT_SOURCE_ID             *sql.Stmt
	SELECT_BANK_INFORMATION      = "SELECT bankcode, name, zip, city, bic FROM BANK_DATA WHERE bankcode = ? AND country = ?;"
	SELECT_BANK_INFORMATION_STMT *sql.Stmt
)

type SQLStore struct {
	db *sql.DB
}

func NewSQLStore(dbType string, url string) *SQLStore {
	db, err := sql.Open(dbType, url)
	if err != nil {
		log.Fatalf("DB Connection error: %v", err)
		return nil
	}

	err = prepareStatements(db)

	if err != nil {
		log.Fatalf("DB Prepare Statement error: %v", err)
		return nil
	}

	return &SQLStore{
		db,
	}
}

func (s *SQLStore) Find(countryCode string, bankCode string) (*BankInfo, error) {
	var dbBankcode, dbName, dbZip, dbCity, dbBic string

	err := SELECT_BANK_INFORMATION_STMT.QueryRow(bankCode, countryCode).Scan(&dbBankcode, &dbName, &dbZip, &dbCity, &dbBic)

	if err != nil {
		return nil, err
	}

	return &BankInfo{
		Bankcode: dbBankcode,
		Name:     dbName,
		Zip:      dbZip,
		City:     dbCity,
		Bic:      dbBic,
	}, nil
}

func (s *SQLStore) Store(data BankInfo) (bool, error) {
	_, err := INSERT_BANK_DATA.Exec(
		data.Source,
		data.Bankcode,
		data.Name,
		data.Zip,
		data.City,
		data.Bic,
		data.Country,
		data.CheckAlgo)
	if err != nil {
		log.Fatalf("Failed to insert %v: %v", err, data)
	}

	return true, nil
}

func (s *SQLStore) Clear(source string) (int, error) {
	sourceID, err := getDataSourceId(source)

	log.Printf("Removing entries for source '%v' (%v)", source, sourceID)
	result, err := s.db.Exec("DELETE FROM BANK_DATA WHERE source = ?;", source)

	if err != nil {
		return -1, err
	}

	n, err := result.RowsAffected()
	if err != nil {
		return -1, err
	}

	return int(n), nil
}

func getDataSourceId(sourceName string) (int, error) {
	var id int
	result := SELECT_SOURCE_ID.QueryRow(sourceName)

	err := result.Scan(&id)

	if err != nil {
		log.Fatalf("Data source %v not found: %v", sourceName, err)
		return -1, err
	}

	return id, nil
}

func prepareStatements(db *sql.DB) error {
	var err error

	INSERT_BANK_DATA, err = db.Prepare(`INSERT INTO BANK_DATA
		(id, source, bankcode, name, zip, city, bic, country, algorithm, created, last_update)
		VALUES
		(NULL, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL);`)

	if err != nil {
		log.Fatalf("Error while preparing statement: %v", err)
		return err
	}

	SELECT_SOURCE_ID, err = db.Prepare(`SELECT id FROM DATA_SOURCE where name = ?`)

	if err != nil {
		log.Fatalf("Error while preparing statement: %v", err)
		return err
	}

	SELECT_BANK_INFORMATION_STMT, err = db.Prepare(SELECT_BANK_INFORMATION)

	if err != nil {
		log.Fatalf("Error while preparing statement: %v", err)
		return err
	}

	return nil
}

package data

// BankInfo describes data associated with an IBAN
type BankInfo struct {
	Bankcode string `json:"bankCode"`
	Name     string `json:"name"`
	Zip      string `json:"zip,omitempty"`
	City     string `json:"city,omitempty"`
	Bic      string `json:"bic,omitempty"`

	Country   string `json:"-"`
	CheckAlgo string `json:"-"`
	Source    string `json:"-"`
}

// BankDataRepository provides storage mechanisms
type BankDataRepository interface {
	// Find an entry
	Find(countryCode string, bankCode string) (*BankInfo, error)

	// Store bank info
	Store(data BankInfo) (bool, error)

	// Clear all entries from a specific source
	//
	// Returns the number of removed entries and an optional error
	Clear(source string) (int, error)
}

package data

type Query struct {
	Country  string
	BankCode string
}

type InMemoryStore struct {
	records map[Query]*BankInfo
}

func NewInMemoryStore() *InMemoryStore {
	return &InMemoryStore{
		records: make(map[Query]*BankInfo),
	}
}

func (s *InMemoryStore) Find(country string, bankCode string) (*BankInfo, error) {
	key := Query{country, bankCode}

	return s.records[key], nil
}

func (s *InMemoryStore) Store(data BankInfo) (bool, error) {
	key := Query{data.Country, data.Bankcode}

	s.records[key] = &data

	return true, nil
}

func (s *InMemoryStore) Clear(source string) (int, error) {
	deleted := 0
	for k, v := range s.records {
		if v.Source == source {
			delete(s.records, k)
			deleted++
		}
	}

	return deleted, nil
}
